import {readiness,finalCaption,platformCaption,PLATFORM_LIMITS,platformTextLength,isActivePost,activePostCounts,editPost,finalReviewStatus} from '/domain.mjs';
import {icon} from '/icons.mjs';
import {DraftBackups} from '/draft-backups.mjs';
import {cleanDisplayTitle,cleanCaptionFirstLine} from '/title-normalization.mjs';
import {reviewEntry} from '/review-entry.mjs';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=p=>[p.source?.display_title,p.source?.label,p.publication_title,p.source?.original_title,p.caption?.split(/\r?\n/)[0].slice(0,45)].map(x=>cleanDisplayTitle(x||'')).find(x=>x&&x!==p.post_id&&x!==p.output_version&&!/^[a-f0-9]{32,}$/i.test(x))||'제목 없는 글';
const finalReviewLabels={unreviewed:'미검토',revise:'수정',discard:'폐기',hold:'보류',passed:'통과'};
const states={all:'전체',waiting:'준비 대기',scheduled:'로컬 예정',running:'모의 실행 중',failed:'실패',reconciliation:'확인 필요',cancelled:'취소',dry_run_complete:'모의 검증 완료'};
let state=null,selected=null,previewPlatform='instagram',slide=0,expanded=false,queueStage='all',timer=null,saveTail=Promise.resolve(),saveFailed=false,conflicted=false,reviewFormVersion=null,slideDirection='',schedulePlan=null,dragging=false,historyRevision=0,finalReviewBusy=false,previewLoading=false,previewGeneration=0,previewCommittedKey='',previewRequestedKey='',verdictSerial=0,activeVerdictBarrier=null,deliveryResults=[];
const localHearts=new Map(),postRows=new Map(),verdictPending=new Map(),verdictFeedback=new Map();
const pending=new Map(),batches=[],draftBackups=new DraftBackups(localStorage,crypto.randomUUID());
const current=()=>state?.posts.find(p=>p.post_id===selected);
const viewerOriginKey='threads_studio_viewer_origin_v1';let viewerAvailable=false,viewerPosts=new Map(),viewerOrigin=null;
function restoreViewerOrigin(){
 try{viewerOrigin=JSON.parse(sessionStorage.getItem(viewerOriginKey)||'null');}catch{viewerOrigin=null;}
 const requested=new URLSearchParams(location.search).get('post')||viewerOrigin?.post_id;
 selected=state.posts.find(p=>p.post_id===requested&&isActivePost(p))?.post_id||state.posts.find(isActivePost)?.post_id||null;
 if(viewerOrigin?.post_id===selected){$('post-search').value=String(viewerOrigin.search||'');if(['all','unreviewed','revise','discard','hold','passed'].includes(viewerOrigin.filter))$('post-status-filter').value=viewerOrigin.filter;previewPlatform=['instagram','threads'].includes(viewerOrigin.platform)?viewerOrigin.platform:'instagram';slide=Math.max(0,Math.min(Number(viewerOrigin.slide)||0,(current()?.images.length||1)-1));}
 const entry=reviewEntry(state.posts,location.search);if(entry){selected=entry.postId;$('post-search').value=entry.search;$('post-status-filter').value=entry.filter;slide=0;}
}
function updateViewerLinks(){const p=visiblePost(),mapped=viewerPosts.get(p?.post_id),link=$('current-full-viewer');$('full-viewer').hidden=!viewerAvailable;link.hidden=!viewerAvailable||!mapped||mapped.output_version!==p?.output_version||JSON.stringify(mapped.images)!==JSON.stringify(p.images.map(i=>i.asset_id));link.href=p?'/viewer/'+encodeURIComponent(p.post_id)+'/':'/viewer/';}
async function loadViewerNavigation(){const n=await api('/api/navigation');viewerAvailable=n.available===true;viewerPosts=new Map((n.posts||[]).map(p=>[p.post_id,p]));updateViewerLinks();}
document.querySelectorAll('[data-viewer-nav]').forEach(link=>link.addEventListener('click',async e=>{e.preventDefault();try{await navigationSettled();await loadViewerNavigation();if(link.hidden)throw Object.assign(Error('viewer_version_changed'),{code:'viewer_version_changed'});sessionStorage.setItem(viewerOriginKey,JSON.stringify({post_id:selected,search:$('post-search').value,filter:$('post-status-filter').value,platform:previewPlatform,slide,scroll:window.scrollY}));location.assign(link.href);}catch(error){notify(error.code==='viewer_version_changed'?'현재 검토 이미지와 제작 원본이 달라 전체 보기 연결을 확인해야 합니다.':friendly(error),true);}}));

const mergePatch=(a,b)=>({...a,...b,...(b.platform_captions?{platform_captions:{...a.platform_captions,...b.platform_captions}}:{})});
const reviewStamp=p=>p?JSON.stringify([p.production_caption_version||null,finalReviewStatus(p).basis]):null;
const visiblePost=()=>{const p=current();if(!p)return null;let out={...p};for(const batch of batches)for(const [id,patch]of batch.edits)if(id===p.post_id)out=mergePatch(out,patch);return mergePatch(out,pending.get(p.post_id)||{});};
// Apply this tab's queued edits through the same pure normalization as the server.
// This also mirrors Instagram caption changes and invalidates an old detail review.
function reviewIntentPost(){const p=current();if(!p)return null;let draft={posts:[p],jobs:[],revision:state.revision};const apply=patch=>{if(patch)draft=editPost(draft,p.post_id,patch,draft.posts[0].revision);};for(const batch of batches)for(const[id,patch]of batch.edits)if(id===p.post_id)apply(patch);apply(pending.get(p.post_id));return draft.posts[0];}
const hasUnsaved=id=>pending.has(id)||batches.some(b=>b.edits.some(([key])=>key===id));
const hasUnsavedContent=id=>[...batches.flatMap(b=>b.edits),...pending.entries()].some(([key,patch])=>key===id&&Object.keys(patch).some(k=>k!=='review_note'));
const postMemo=p=>p?.review_note??p?.review?.note??'';
const reviewStatus=p=>!p||hasUnsavedContent(p.post_id)?'unreviewed':(Object.hasOwn(finalReviewLabels,p.final_review_status)?p.final_review_status:'unreviewed');
const assetURL=im=>'/assets/'+im.asset_id;
function notify(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
async function api(route,body){const r=await fetch(route,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'content-type':'application/json','x-studio-local':'1'},body:body===undefined?undefined:JSON.stringify(body)});const result=await r.json();if(Array.isArray(result.finalReview?.deliveryResults)&&(!state||!result.state||result.state.revision>=state.revision))deliveryResults=result.finalReview.deliveryResults;if(!r.ok)throw Object.assign(new Error(result.code||'local_operation_failed'),{code:result.code,status:r.status});return result;}
function friendly(e){const names={final_review_required:'현재 내용의 최종 검토를 통과한 글만 대기 목록에 넣을 수 있습니다.',invalid_final_review:'최종 검토 판정을 다시 선택해 주세요.',ffmpeg_not_installed:'FFmpeg가 설치되거나 경로에 등록되지 않았습니다. 설치 작업은 별도 승인 후 진행합니다.',ffmpeg_failed:'로컬 영상 변환에 실패했습니다. 원본 이미지와 편집은 보존합니다.',reel_cancelled:'영상 생성을 중단했습니다.',video_size_limit:'영상 파일은 300MB 이내여야 합니다.',reel_video_required:'실제 MP4·MOV 영상 파일을 준비해 주세요.',connection_public_config_required:'공개 앱 ID와 플랫폼을 확인해 주세요.',connection_redirect_invalid:'등록한 HTTPS 회신 주소를 입력해 주세요.',two_topic_tags_required:'글별 주제 태그를 두 개 함께 입력해 주세요.',invalid_tag:'주제 태그는 문자·숫자·밑줄만 사용해 주세요.',invalid_threads_topic:'Threads 주제 태그는 #·줄바꿈 없이 50자 이내로 입력해 주세요.',undo_unavailable:'되돌릴 이전 저장본이 없습니다.',redo_unavailable:'다시 실행할 저장본이 없습니다.',history_unavailable:'선택한 저장본을 찾지 못했습니다.',production_title_contract_changed:'원본 표지 제목 입력 계약을 확인해 주세요.',review_form_version_changed:'검수 중 글 또는 제작 버전이 바뀌었습니다. 현재 버전 검수를 다시 불러온 후 직접 확인해 주세요.',production_unavailable:'제작 자료 폴더를 찾지 못했습니다. START.ps1의 MaterialRoot 인자로 실제 자료 폴더를 지정해 주세요.',production_version_changed:'제작 결과가 변경되었습니다. 목록을 다시 열어 현재 버전을 선택해 주세요.',production_image_changed:'원본 이미지 해시가 제작 기록과 다릅니다. 해당 결과를 다시 제작한 후 가져오세요.',production_path_invalid:'허용된 제작 결과 폴더 밖의 파일은 가져오지 않습니다.',revision_conflict:'다른 창에서 이 글을 변경했습니다. 미저장 문안을 보존했으니 새로고침 후 비교해 주세요.',review_required:'원문·권리·현재 버전 검수를 먼저 확인해 주세요.',stale_job:'작성 내용이 바뀐 대기 항목입니다. 현재 글에서 새 대기 항목을 저장해 주세요.',asset_not_found:'이 컴퓨터의 이미지 파일이 없습니다. 해당 이미지를 먼저 선택해 주세요.',same_version_import_conflict:'같은 글·버전이 이미 있습니다. 기존 편집을 보호하기 위해 가져오기를 중단했습니다.',running_stop_required:'진행 중인 모의 실행은 중단 요청으로 멈춰 주세요.',reconciliation_required:'중복 실행을 막기 위해 이전 실행 결과 확인이 필요합니다.',state_corrupt:'저장 파일을 읽지 못했습니다. 이전 저장본 복원이 필요합니다.',invalid_local_time:'유효한 예약 시각을 입력해 주세요.',secret_field_forbidden:'비밀번호·토큰·키 필드가 있는 파일은 불러오지 않습니다.'};return names[e.code]||'로컬 작업을 완료하지 못했습니다. 편집은 보존됩니다. 다시 시도하거나 저장본을 확인해 주세요.';}
function persistBackup(){try{const data={};for(const batch of batches)for(const [id,patch]of batch.edits){const p=state.posts.find(x=>x.post_id===id);data[id]={expected_revision:p.revision,patch:mergePatch(data[id]?.patch||{},patch)};}for(const [id,patch]of pending){const p=state.posts.find(x=>x.post_id===id);data[id]={expected_revision:p.revision,patch:mergePatch(data[id]?.patch||{},patch)};}draftBackups.persist(data);}catch{notify('브라우저의 미저장 백업 공간이 부족합니다. 저장이 끝날 때까지 창을 닫지 마세요.',true);}}
function schedule(patch){if(!current())return;pending.set(selected,mergePatch(pending.get(selected)||{},patch));persistBackup();$('save-state').textContent='저장 대기…';renderPreview();renderLimits();renderFinalReview();renderPostMemo();renderPosts();clearTimeout(timer);timer=setTimeout(()=>flush().catch(()=>{}),500);}
function flush(){clearTimeout(timer);const batch={edits:[...pending.entries()]};pending.clear();if(batch.edits.length)batches.push(batch);saveTail=saveTail.then(async()=>{try{if(conflicted)throw Object.assign(new Error('revision_conflict'),{code:'revision_conflict'});while(batch.edits.length){const [id,patch]=batch.edits[0],p=state.posts.find(x=>x.post_id===id);const result=await api('/api/posts/'+encodeURIComponent(id),{expected_revision:p.revision,patch});state=result.state;if(id===selected&&p.review&&!state.posts.find(x=>x.post_id===id).review){$('review-score').value='';$('review-approved').checked=false;$('review-note').value='';}batch.edits.shift();saveFailed=false;persistBackup();renderPosts();renderQueue();renderHistory();updateIdentity();renderLimits();$('save-state').textContent=pending.size?'저장 대기…':'로컬 저장 완료';refreshEditHistory().catch(()=>{});}}catch(e){for(const [id,patch]of batch.edits)pending.set(id,mergePatch(patch,pending.get(id)||{}));if(e.status===409||e.code==='revision_conflict')conflicted=true;saveFailed=true;persistBackup();$('save-state').textContent='저장 실패 · 편집 보존';renderPostMemo();notify(friendly(e),true);throw e;}finally{const i=batches.indexOf(batch);if(i>=0)batches.splice(i,1);persistBackup();}});const out=saveTail;saveTail=out.catch(()=>{});return out;}
async function settled(){await flush();await saveTail;if(saveFailed||conflicted)throw Object.assign(new Error('revision_conflict'),{code:'revision_conflict'});}
async function navigationSettled(){if(activeVerdictBarrier&&!pending.size&&!batches.length){await activeVerdictBarrier.editBarrier;if(saveFailed||conflicted)throw Object.assign(new Error('revision_conflict'),{code:'revision_conflict'});return;}await settled();}
function acceptNewState(next){if(!next||state&&next.revision<=state.revision)return false;state=next;return true;}
function updateIdentity(){const p=current();const versionChanged=!!p&&reviewFormVersion!==null&&reviewFormVersion!==reviewStamp(p);$('review-version-change').hidden=!versionChanged;$('save-review').disabled=versionChanged;$('identity').textContent=p?label(p)+' · 이미지 '+p.images.length+'장':'';$('review-identity').textContent=p?'현재 저장본 · 이미지 순서와 문안이 바뀌면 검수·모의 실행 승인을 다시 확인합니다.':'';if(p){renderFinalReview();renderPostMemo();$('approval-state').textContent=p.approval?'이 내용의 모의 실행 승인 완료 · 실제 게시 승인 없음':'게시 승인 대기 · 모의 실행 검수 전';$('approve').disabled=readiness(p).some(x=>!['account_unconnected','public_media_required','instagram_jpeg_required'].includes(x.code));}}
function renderFinalReview(){const p=visiblePost();if(!p)return;const status=reviewStatus(p),request=verdictPending.get(p.post_id);$('final-review-status').textContent=finalReviewLabels[status]+(hasUnsavedContent(p.post_id)?' · 편집 저장 대기':'');$('final-review-status').dataset.status=status;$('final-review-save-status').textContent=request?finalReviewLabels[request.decision]+' 저장 중…':verdictFeedback.get(p.post_id)||'';document.querySelectorAll('[data-final-review]').forEach(b=>{b.disabled=finalReviewBusy||conflicted||previewLoading;b.setAttribute('aria-pressed',b.dataset.finalReview===status);});$('add-queue').disabled=status!=='passed'||finalReviewBusy||conflicted||previewLoading;$('review-handoff').disabled=finalReviewBusy||conflicted||saveFailed||previewLoading;renderDelivery(p);}
const deliveryLabels={pending:'대기',scheduled:'예약됨',sending:'전송 중',error:'오류',partially_posted:'일부게시',posted:'게시완료'};
const httpsLink=value=>{try{return typeof value==='string'&&new URL(value).protocol==='https:'?value:null;}catch{return null;}};
function deliveryTime(value,label){if(typeof value!=='string'||!Number.isFinite(Date.parse(value)))return '';return '<p class="delivery-time">'+label+' <time datetime="'+esc(value)+'">'+esc(new Date(value).toLocaleString('ko-KR'))+'</time></p>';}
function renderDelivery(p){const result=!hasUnsavedContent(p.post_id)&&deliveryResults.find(r=>r.postId===p.post_id&&r.outputVersion===p.output_version);if(!result){$('delivery-results').innerHTML='<p class="help">현재 버전의 Buffer 전달 기록 없음</p>';return;}const rows=(result.selectedPlatforms||[]).filter(k=>['instagram','threads'].includes(k)).map(k=>{const record=result.platforms?.[k]||{},complete=record.completed===true,link=complete&&httpsLink(record.externalUrl),status=complete?'게시완료':deliveryLabels[record.status]||'대기';return '<div class="delivery-platform"><span>'+(k==='instagram'?'Instagram':'Threads')+' · '+esc(status)+'</span>'+(link?'<a href="'+esc(link)+'" target="_blank" rel="noopener noreferrer">게시물 열기</a>':'')+(complete?deliveryTime(record.publishedAt,'실제 게시 시각'):record.status==='scheduled'?deliveryTime(record.scheduledAt,'예정 시각'):'')+'</div>';});$('delivery-results').innerHTML='<p class="delivery-summary">'+esc(deliveryLabels[result.deliveryStatus]||'대기')+'</p>'+rows.join('');}
function renderPostMemo(){const p=visiblePost();if(!p)return;if(document.activeElement!==$('post-review-note'))$('post-review-note').value=postMemo(p);const dirty=[...batches.flatMap(b=>b.edits),...pending.entries()].some(([id,patch])=>id===p.post_id&&Object.hasOwn(patch,'review_note'));$('review-note-save-status').textContent=saveFailed||conflicted?'메모 저장 실패 · 입력 보존':dirty?'메모 저장 대기…':postMemo(p)?'메모 저장 완료':'메모 없음 · 자동 저장';}
$('post-review-note').addEventListener('input',()=>schedule({review_note:$('post-review-note').value}));
function show(view){document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==view);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='queue')renderQueue();if(view==='history')renderHistory();}
function renderPosts(){if(!state)return;const q=$('post-search').value.toLowerCase(),filter=$('post-status-filter').value,list=$('post-list');const posts=state.posts.filter(isActivePost).filter(p=>filter==='all'||reviewStatus(p)===filter).filter(p=>(label(p)+' '+p.post_id+' '+p.caption+' '+platformCaption(p,'threads')).toLowerCase().includes(q));$('post-filter-count').textContent=posts.length+'개 글';const visible=new Set();for(const[pIndex,p]of posts.entries()){visible.add(p.post_id);let button=postRows.get(p.post_id);if(!button){button=document.createElement('button');button.dataset.post=p.post_id;const thumb=document.createElement('span');thumb.className='mini empty-mini';thumb.textContent='문안';const text=document.createElement('span'),title=document.createElement('strong'),meta=document.createElement('small');text.append(title,meta);button.append(thumb,text);button.onclick=async()=>{try{await navigationSettled();selected=button.dataset.post;slide=0;expanded=false;renderEditor();}catch(e){notify(friendly(e),true);}};postRows.set(p.post_id,button);}button.className='post-item '+(p.post_id===selected?'active':'');button.querySelector('strong').textContent=label(p);button.querySelector('small').textContent=p.images.length+'장 · '+finalReviewLabels[reviewStatus(p)]+(verdictPending.has(p.post_id)?' · 저장 중…':'');const old=button.firstElementChild,im=p.images[0];if(im){const src=assetURL(im);if(old.tagName==='IMG'){if(old.getAttribute('src')!==src)old.src=src;}else{const thumb=new Image();thumb.className='mini';thumb.alt='';thumb.src=src;old.replaceWith(thumb);}}else if(old.tagName==='IMG'){const thumb=document.createElement('span');thumb.className='mini empty-mini';thumb.textContent='문안';old.replaceWith(thumb);}if(list.children[pIndex]!==button)list.insertBefore(button,list.children[pIndex]||null);}for(const button of [...list.children])if(!visible.has(button.dataset.post))button.remove();const stored=new Set(state.posts.map(p=>p.post_id));for(const[id,button]of postRows)if(!stored.has(id)){button.remove();postRows.delete(id);}}
function renderEditor(){updateViewerLinks();const p=visiblePost();reviewFormVersion=reviewStamp(p);$('empty-editor').hidden=!!p;$('composer').hidden=!p;$('preview-column').hidden=!p;renderPosts();updateIdentity();if(!p){previewGeneration++;previewRequestedKey='';return;}$('post-review-note').value=postMemo(p);renderPostMemo();renderCaptionEditor();$('tags').value=p.tags;$('topic-one').value=p.topic_tags?.[0]||'';$('topic-two').value=p.topic_tags?.[1]||'';$('threads-topic').value=p.threads_topic_tag||'';$('media-format').value=p.media_format||'images';$('reel-controls').hidden=p.media_format!=='reel';$('reel-reviewed').checked=p.reel_playback_reviewed===true;$('music-mode').value=p.music?.mode||'silent';document.querySelectorAll('[data-common-tag]').forEach(x=>x.checked=(state.common_tags||[]).includes(x.dataset.commonTag));document.querySelectorAll('[data-platform]').forEach(b=>b.setAttribute('aria-pressed',p.targets.includes(b.dataset.platform)));document.querySelectorAll('[name=timing]').forEach(x=>x.checked=x.value===p.timing.mode);$('local-time').value=localDisplay(p.timing);$('local-time').disabled=p.timing.mode!=='planned';renderProductionFeedback(p);$('source-url').value=p.source.url;$('source-verified').checked=p.source.verified;for(const k of ['fact','rights','privacy','defamation','platform_policy'])$('safety-'+k).value=p.safety[k];$('warn-note').value=p.safety.warn_note;$('review-score').value=p.review?.score||'';$('review-approved').checked=p.review?.decision==='approved';$('review-note').value=p.review?.note||'';renderImages();renderPreview();renderLimits();refreshEditHistory().catch(e=>notify(friendly(e),true));}
function renderProductionFeedback(p){const quality=p.production_feedback;const currentQuality=quality?.current?.output_version===p.output_version?quality.current:null;$('production-feedback').textContent=currentQuality?'기존 제작 평가 '+(currentQuality.score??'미평가')+'/10 · 현재 제작 버전 일치 · 읽기 전용\n'+currentQuality.note+'\n이 글의 게시 검수·승인은 아래에서 별도로 확인합니다.':quality?.previous?'기존 다른 버전 평가 '+(quality.previous.score??'미평가')+'/10 · 현재 버전 미평가 · 읽기 전용':'기존 제작 평가 정보 없음 · 현재 문안의 직접 평가가 필요합니다.';}
function localDisplay(t){if(!t.due_at)return '';const d=new Date(t.due_at);const z=x=>String(x).padStart(2,'0');return d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate())+'T'+z(d.getHours())+':'+z(d.getMinutes());}
