$('add-queue').addEventListener('click',()=>action(async()=>{await settled();const p=current();if(previewLoading)throw Object.assign(new Error('review_form_version_changed'),{code:'review_form_version_changed'});if(reviewStatus(p)!=='passed')throw Object.assign(new Error('final_review_required'),{code:'final_review_required'});const r=await api('/api/queue',{post_id:p.post_id,expected_revision:p.revision});state=r.state;renderQueue();notify('로컬 대기 목록에 저장했습니다. 실제 게시·예약 등록은 없습니다.');}));
$('review-handoff').addEventListener('click',()=>action(async()=>{if(finalReviewBusy)return;await settled();const r=await api('/api/final-review/handoff',{expected_revision:state.revision});$('handoff-result').textContent=r.count+'개 현재 통과본 · '+r.path+' · 외부 요청 0회';notify('현재 통과본 인계 파일 저장 · 실제 게시·예약 없음');}));
document.querySelectorAll('[data-final-review]').forEach(b=>b.addEventListener('click',async()=>{if(finalReviewBusy||previewLoading)return;const id=selected,decision=b.dataset.finalReview,sequence=++verdictSerial;verdictPending.set(id,{decision,sequence});verdictFeedback.delete(id);finalReviewBusy=true;renderFinalReview();renderPosts();try{const p=visiblePost(),one=$('topic-one').value.trim(),two=$('topic-two').value.trim();if(!!one!==!!two)throw Object.assign(new Error('two_topic_tags_required'),{code:'two_topic_tags_required'});const patch={};if($('tags').value!==p.tags)patch.tags=$('tags').value;if(JSON.stringify(one?[one,two]:[])!==JSON.stringify(p.topic_tags||[]))patch.topic_tags=one?[one,two]:[];if($('threads-topic').value!==p.threads_topic_tag)patch.threads_topic_tag=$('threads-topic').value;if(!$('caption').readOnly&&$('caption').value!==platformCaption(p,previewPlatform))patch.platform_captions={[previewPlatform]:$('caption').value};if(Object.keys(patch).length)schedule(patch);const intended=reviewIntentPost(),intendedStamp=reviewStamp(intended),expectedBasis=finalReviewStatus(intended).basis,expectedOutputVersion=intended.output_version;await settled();const editBarrier=saveTail,operation=editBarrier.then(async()=>{if(id!==selected)throw Object.assign(new Error('review_form_version_changed'),{code:'review_form_version_changed'});const post=current();if(previewLoading||reviewStamp(post)!==intendedStamp||reviewStamp(reviewIntentPost())!==intendedStamp)throw Object.assign(new Error('review_form_version_changed'),{code:'review_form_version_changed'});const r=await api('/api/final-review',{post_id:id,decision,expected_revision:post.revision,expected_output_version:expectedOutputVersion,expected_basis:expectedBasis}),selectedStamp=reviewStamp(current());acceptNewState(r.state);if(verdictPending.get(id)?.sequence!==sequence)return;verdictFeedback.set(id,'최종 검토 '+finalReviewLabels[decision]+' 저장 완료');if(reviewStamp(current())!==selectedStamp){if(document.activeElement!==$('caption')&&!hasUnsaved(selected))renderCaptionEditor();renderPreview();renderLimits();}renderPosts();updateIdentity();renderQueue();refreshEditHistory().catch(()=>{});if(selected===id)notify('최종 검토 '+finalReviewLabels[decision]+' 저장 · 실제 게시·예약 없음');});activeVerdictBarrier={sequence,editBarrier};saveTail=operation.catch(()=>{});await operation;}catch(e){if(e.status===409||e.code==='revision_conflict')conflicted=true;verdictFeedback.set(id,'판정 저장 실패 · 다시 확인해 주세요');if(selected===id)notify(friendly(e),true);}finally{if(activeVerdictBarrier?.sequence===sequence)activeVerdictBarrier=null;if(verdictPending.get(id)?.sequence===sequence)verdictPending.delete(id);finalReviewBusy=verdictPending.size>0;renderPosts();renderFinalReview();}}));
$('save-review').addEventListener('click',()=>action(async()=>{const formId=selected,formVersion=reviewFormVersion;await settled();const p=current();if(!p||p.post_id!==formId||reviewStamp(p)!==formVersion||reviewFormVersion!==reviewStamp(p))throw Object.assign(new Error('review_form_version_changed'),{code:'review_form_version_changed'});const safety={warn_note:$('warn-note').value};for(const k of ['fact','rights','privacy','defamation','platform_policy'])safety[k]=$('safety-'+k).value;const score=Number($('review-score').value),review=score?{output_version:p.output_version,score,decision:$('review-approved').checked?'approved':'pending',note:$('review-note').value}:null;const r=await api('/api/posts/'+encodeURIComponent(p.post_id),{expected_revision:p.revision,patch:{source:{...p.source,url:$('source-url').value,verified:$('source-verified').checked},safety,review}});state=r.state;renderEditor();notify('직접 확인한 검수 정보를 로컬에 저장했습니다.');}));
