$('image-file').addEventListener('change',()=>action(async()=>{await settled();const id=selected,images=[...current().images];for(const file of $('image-file').files){if(file.size>10000000)throw Object.assign(new Error('asset_size_limit'),{code:'asset_size_limit'});const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const r=await api('/api/assets',{name:file.name,mime:file.type,base64:String(data).split(',')[1]});images.push({asset_id:r.asset.asset_id,order:images.length+1,mime:r.asset.mime});}const p=state.posts.find(x=>x.post_id===id),r=await api('/api/posts/'+encodeURIComponent(id),{expected_revision:p.revision,patch:{images}});state=r.state;$('image-file').value='';renderEditor();notify('이미지를 로컬에만 저장했습니다. 현재 내용은 다시 검수해 주세요.');}));
