function renderCaptionEditor(){const p=visiblePost();if(!p)return;$('caption').value=platformCaption(p,previewPlatform);$('caption').readOnly=previewPlatform==='threads'&&p.threads_title_only;$('caption-platform-title').textContent=(previewPlatform==='instagram'?'Instagram':'Threads')+' 문안';document.querySelectorAll('[data-caption-platform]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.captionPlatform===previewPlatform));$('caption-origin').textContent=previewPlatform==='threads'&&p.threads_title_only?'실제 표지 제목만 게시합니다. 저장된 기존 문안은 보존합니다.':p.platform_caption_edited?.[previewPlatform]?'사용자 수정 문안 · 제작 갱신 시 보존':p.production_caption_status==='authored'?'원문 기반 제작 문안 · 플랫폼별 작성':p.production_caption_status==='awaiting-authored-captions'?'원문 기반 문안 작성 대기 · 제작이 완료되면 자동 연결':p.production_caption_status?.startsWith('held-')?'문안 입력 계약 확인 대기 · 게시 보류':'로컬 문안';}
function slideFinish(track,direction,targetSlide){if(!track)return;const gesturePost=selected,gesturePlatform=previewPlatform,gestureGeneration=previewGeneration;dragging=true;track.style.transition=matchMedia('(prefers-reduced-motion: reduce)').matches?'none':'transform 180ms ease-out';track.style.transform='translateX('+(-100-direction*100)+'%)';let finished=false;const finish=()=>{if(finished)return;finished=true;dragging=false;const p=visiblePost();if(p&&direction&&selected===gesturePost&&previewPlatform===gesturePlatform&&previewGeneration===gestureGeneration)slide=targetSlide===undefined?(slide+direction+p.images.length)%p.images.length:targetSlide;renderPreview();};track.addEventListener('transitionend',finish,{once:true});setTimeout(finish,200);}
function moveSlide(direction){const p=visiblePost();if(!p||p.images.length<2||dragging)return;if(previewLoading){slide=(slide+direction+p.images.length)%p.images.length;renderPreview();return;}slideFinish($('preview').querySelector('.carousel-track'),direction);}
function jumpSlide(index){const p=visiblePost();if(!p||dragging||!Number.isInteger(index)||index<0||index>=p.images.length||index===slide)return;if(previewLoading){slide=index;renderPreview();return;}slideFinish($('preview').querySelector('.carousel-track'),index>slide?1:-1,index);}
function attachSwipe(){const frame=$('preview').querySelector('.media-frame'),track=frame?.querySelector('.carousel-track');if(!frame)return;frame._swipeAbort?.abort();if(!track||visiblePost().images.length<2)return;const swipeAbort=new AbortController();frame._swipeAbort=swipeAbort;const listen=(name,fn)=>frame.addEventListener(name,fn,{signal:swipeAbort.signal});let start=null;
listen('pointerdown',e=>{if(e.target.closest('button')||dragging||previewLoading||e.button!==0)return;start={x:e.clientX,y:e.clientY,id:e.pointerId,lastX:e.clientX,lastT:performance.now(),velocity:0};dragging=true;track.style.transition='none';frame.setPointerCapture?.(e.pointerId);});
listen('pointermove',e=>{if(!start||start.id!==e.pointerId)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dy)>Math.abs(dx)*1.4&&Math.abs(dy)>12){start=null;slideFinish(track,0);return;}const now=performance.now(),dt=now-start.lastT;start.velocity=dt>0?(e.clientX-start.lastX)/dt:start.velocity;start.lastX=e.clientX;start.lastT=now;track.style.transform='translateX(calc(-100% + '+dx+'px))';});
listen('pointerup',e=>{if(!start||start.id!==e.pointerId)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)<3&&Math.abs(dy)<3){start=null;dragging=false;track.style.transform='translateX(-100%)';return;}const v=performance.now()-start.lastT<120?start.velocity:0;const advance=Math.abs(dx)>frame.clientWidth*.2||(Math.abs(dx)>12&&Math.abs(v)>.45);const direction=advance&&Math.abs(dx)>Math.abs(dy)*1.4?(dx<0?1:-1):0;start=null;slideFinish(track,direction);});listen('pointercancel',()=>{if(!start)return;start=null;slideFinish(track,0);});}
