async function loadSchedule(){const {defaults}=await api('/api/schedule-defaults');$('schedule-date').value=defaults.date||seoulDate();$('schedule-interval').value=String(defaults.interval_minutes);$('schedule-windows').innerHTML=defaults.windows.map((w,i)=>'<div class="schedule-window"><label>시작<input type="time" data-window-start="'+i+'" value="'+w.start+'"></label><span>–</span><label>끝<input type="time" data-window-end="'+i+'" value="'+w.end+'"></label></div>').join('');}
function scheduleConfig(){return {timezone:'Asia/Seoul',date:$('schedule-date').value,interval_minutes:Number($('schedule-interval').value),windows:[...$('schedule-windows').querySelectorAll('[data-window-start]')].map(x=>({start:x.value,end:$('schedule-windows').querySelector('[data-window-end="'+x.dataset.windowStart+'"]').value}))};}
$('schedule-preview').addEventListener('click',()=>action(async()=>{await settled();schedulePlan=await api('/api/queue-schedule/preview',{config:scheduleConfig()});const p=schedulePlan;$('schedule-result').textContent='플랫폼별 '+p.capacity_per_platform+'개 슬롯 · Instagram '+p.counts.instagram.assigned+'개 / 초과 '+p.counts.instagram.overflow+'개 · Threads '+p.counts.threads.assigned+'개 / 초과 '+p.counts.threads.overflow+'개\n'+p.assignments.map(a=>label(state.posts.find(x=>x.post_id===a.post_id))+' · '+Object.entries(a.slots).map(([k,t])=>k+' '+t.local.slice(11)).join(' / ')).join('\n');$('schedule-apply').disabled=false;}));
$('schedule-apply').addEventListener('click',()=>action(async()=>{if(!schedulePlan)return;const plan=schedulePlan;await settled();$('schedule-apply').disabled=true;const operation=saveTail.then(async()=>{const r=await api('/api/queue-schedule/apply',{config:plan.config,expected_revision:plan.state_revision});state=r.state;schedulePlan=null;renderQueue();updateIdentity();notify('로컬 예정표 저장 · 초과 항목은 대기 유지 · 실제 예약 없음');});saveTail=operation.catch(()=>{});await operation;}));
$('queue').addEventListener('change',e=>{if(e.target.closest('.schedule-form')){schedulePlan=null;$('schedule-apply').disabled=true;}});

const safetyLabels={fact:'사실 일치',rights:'권리',privacy:'개인정보·초상',defamation:'명예훼손·단정',platform_policy:'플랫폼 원본성'};$('safety-fields').innerHTML=Object.entries(safetyLabels).map(([key,text])=>'<label for="safety-'+key+'">'+text+'<select id="safety-'+key+'"><option value="UNKNOWN">미확인</option><option value="PASS">확인 완료</option><option value="WARN">주의·메모 필요</option><option value="BLOCK">게시 보류</option></select></label>').join('');
try{state=(await api('/api/state')).state;restoreViewerOrigin();renderEditor();await loadViewerNavigation();if(viewerOrigin?.post_id===selected)requestAnimationFrame(()=>window.scrollTo(0,Number(viewerOrigin.scroll)||0));renderQueue();renderHistory();notify('로컬 저장을 불러왔습니다. 외부 게시 기능은 잠겨 있습니다.');renderRecoveries();await loadSchedule();setInterval(()=>{if(!productionBusy&&!$('production-dialog').open&&!conflicted)syncProduction().catch(()=>{});},15000);await syncProduction(null,true);}catch(e){notify(friendly(e),true);if(e.code==='state_corrupt'){const button=document.createElement('button');button.textContent='이전 로컬 저장본 복원';button.className='small';button.addEventListener('click',()=>action(async()=>{state=(await api('/api/restore-backup',{})).state;selected=state.posts[0]?.post_id||null;renderEditor();notify('이전 저장본을 복원했습니다. 손상된 파일도 보존했습니다.');}));$('status').append(' ',button);}}
